insert into public.question_solutions (question_id, final_answer_markdown, explanation_markdown) values ('40000000-0000-4000-8000-000000900055', '$F(0,0)
insert into public.question_solution_steps (id, question_id, title, content_markdown, sort_order) values ('70000000-0000-4000-8000-000009000551', '40000000-0000-4000-8000-000000900055', 'Use uma condição necessária', 'Se $F$ fosse linear, teríamos $F(0)=0$.', 1), ('70000000-0000-4000-8000-000009000552', '40000000-0000-4000-8000-000000900055', 'Calcule a imagem do zero', '$F(0,0)=(1,0)$.', 2), ('70000000-0000-4000-8000-000009000553', '40000000-0000-4000-8000-000000900055', 'Compare', 'O vetor $(1,0)$ não é o vetor nulo.', 3), ('70000000-0000-4000-8000-000009000554', '40000000-0000-4000-8000-000000900055', 'Conclua', 'A condição necessária falha, portanto $F$ não é linear.', 4)
insert into public.questions (id, subject_id, source_id, kind, difficulty, publication_status, statement_markdown) values ('40000000-0000-4000-8000-000000900056', '20000000-0000-4000-8000-000000000002', '10000000-0000-4000-8000-000000090004', 'multiple_choice', 'easy', 'published', 'Para $T(x,y)=(x+y,0)$, qual é $\ker T$?')
insert into public.question_options (id, question_id, label, content_markdown, sort_order) values ('50000000-0000-4000-8000-000009000561', '40000000-0000-4000-8000-000000900056', 'A', '${(0,0)}$', 1), ('50000000-0000-4000-8000-000009000562', '40000000-0000-4000-8000-000000900056', 'B', '$\operatorname{span}\{(1,-1)\}$', 2), ('50000000-0000-4000-8000-000009000563', '40000000-0000-4000-8000-000000900056', 'C', '$\operatorname{span}\{(1,1)\}$', 3), ('50000000-0000-4000-8000-000009000564', '40000000-0000-4000-8000-000000900056', 'D', '$\operatorname{span}\{(1,0)\}$', 4)
insert into public.question_answer_keys (question_id, correct_option_id) values ('40000000-0000-4000-8000-000000900056', '50000000-0000-4000-8000-000009000562') on conflict (question_id) do update set correct_option_id=excluded.correct_option_id;
insert into public.question_taxonomy_tags (question_id, taxonomy_node_id, is_primary) values ('40000000-0000-4000-8000-000000900056', '30000000-0000-4000-8000-000000090014', true) on conflict (question_id, taxonomy_node_id) do update set is_primary=excluded.is_primary;
insert into public.question_hints (id, question_id, content_markdown, sort_order) values ('60000000-0000-4000-8000-000009000561', '40000000-0000-4000-8000-000000900056', 'O núcleo reúne entradas enviadas ao vetor nulo.', 1), ('60000000-0000-4000-8000-000009000562', '40000000-0000-4000-8000-000000900056', 'Imponha $x+y=0$.', 2), ('60000000-0000-4000-8000-000009000563', '40000000-0000-4000-8000-000000900056', 'Use uma variável livre para parametrizar as soluções.', 3)
insert into public.question_solutions (question_id, final_answer_markdown, explanation_markdown) values ('40000000-0000-4000-8000-000000900056', '$\operatorname{span}\{(1,-1)\}$', 'A segunda componente da saída já é sempre zero; a primeira impõe uma única relação. As soluções têm uma variável livre e formam a reta de direção $(1,-1)$.') on conflict (question_id) do update set final_answer_markdown=excluded.final_answer_markdown, explanation_markdown=excluded.explanation_markdown;
insert into public.question_solution_steps (id, question_id, title, content_markdown, sort_order) values ('70000000-0000-4000-8000-000009000561', '40000000-0000-4000-8000-000000900056', 'Imponha saída nula', '$T(x,y)=(0,0)$ exige $x+y=0$.', 1), ('70000000-0000-4000-8000-000009000562', '40000000-0000-4000-8000-000000900056', 'Isole uma variável', '$y=-x$.', 2), ('70000000-0000-4000-8000-000009000563', '40000000-0000-4000-8000-000000900056', 'Parametrize', '$(x,y)=x(1,-1)$.', 3), ('70000000-0000-4000-8000-000009000564', '40000000-0000-4000-8000-000000900056', 'Conclua', 'O núcleo é o espaço gerado por $(1,-1)$.', 4)
insert into public.questions (id, subject_id, source_id, kind, difficulty, publication_status, statement_markdown) values ('40000000-0000-4000-8000-000000900057', '20000000-0000-4000-8000-000000000002', '10000000-0000-4000-8000-000000090004', 'multiple_choice', 'easy', 'published', 'A transformação $T:\mathbb R^2\to\mathbb R^3$ tem matriz $A=\begin{pmatrix}1&0\\2&0\\0&1\end{pmatrix}$. Qual conjunto gera $\operatorname{Im}T$?')
insert into public.question_options (id, question_id, label, content_markdown, sort_order) values ('50000000-0000-4000-8000-000009000571', '40000000-0000-4000-8000-000000900057', 'A', '$\{(1,2,1)\}$', 1), ('50000000-0000-4000-8000-000009000572', '40000000-0000-4000-8000-000000900057', 'B', '$\{(1,0,0),(0,2,1)\}$', 2), ('50000000-0000-4000-8000-000009000573', '40000000-0000-4000-8000-000000900057', 'C', '$\{(1,2,0),(0,0,1)\}$', 3), ('50000000-0000-4000-8000-000009000574', '40000000-0000-4000-8000-000000900057', 'D', '$\{(1,0),(2,0),(0,1)\}$', 4)
insert into public.question_answer_keys (question_id, correct_option_id) values ('40000000-0000-4000-8000-000000900057', '50000000-0000-4000-8000-000009000573') on conflict (question_id) do update set correct_option_id=excluded.correct_option_id;
insert into public.question_taxonomy_tags (question_id, taxonomy_node_id, is_primary) values ('40000000-0000-4000-8000-000000900057', '30000000-0000-4000-8000-000000090014', true) on conflict (question_id, taxonomy_node_id) do update set is_primary=excluded.is_primary;
insert into public.question_hints (id, question_id, content_markdown, sort_order) values ('60000000-0000-4000-8000-000009000571', '40000000-0000-4000-8000-000000900057', 'A imagem de uma transformação matricial é o espaço coluna.', 1), ('60000000-0000-4000-8000-000009000572', '40000000-0000-4000-8000-000000900057', 'Leia cada coluna como a imagem de um vetor da base padrão.', 2), ('60000000-0000-4000-8000-000009000573', '40000000-0000-4000-8000-000000900057', 'As duas colunas são independentes.', 3)
insert into public.question_solutions (question_id, final_answer_markdown, explanation_markdown) values ('40000000-0000-4000-8000-000000900057', '$\{(1,2,0),(0,0,1)\}$', 'Cada saída $Ax$ é uma combinação das colunas de $A$. Por isso a imagem é gerada pelas colunas, que neste caso apontam em duas direções independentes de $\mathbb R^3$.') on conflict (question_id) do update set final_answer_markdown=excluded.final_answer_markdown, explanation_markdown=excluded.explanation_markdown;
insert into public.question_solution_steps (id, question_id, title, content_markdown, sort_order) values ('70000000-0000-4000-8000-000009000571', '40000000-0000-4000-8000-000000900057', 'Leia a primeira coluna', '$T(e_1)=(1,2,0)$.', 1), ('70000000-0000-4000-8000-000009000572', '40000000-0000-4000-8000-000000900057', 'Leia a segunda coluna', '$T(e_2)=(0,0,1)$.', 2), ('70000000-0000-4000-8000-000009000573', '40000000-0000-4000-8000-000000900057', 'Descreva saídas gerais', '$T(x,y)=x(1,2,0)+y(0,0,1)$.', 3), ('70000000-0000-4000-8000-000009000574', '40000000-0000-4000-8000-000000900057', 'Conclua', 'Esses dois vetores geram toda a imagem.', 4)
insert into public.questions (id, subject_id, source_id, kind, difficulty, publication_status, statement_markdown) values ('40000000-0000-4000-8000-000000900058', '20000000-0000-4000-8000-000000000002', '10000000-0000-4000-8000-000000090004', 'multiple_choice', 'easy', 'published', 'Uma transformação linear satisfaz $T(1,0)=(2,-1)$ e $T(0,1)=(3,4)$. Qual é sua matriz na base padrão?')
insert into public.question_options (id, question_id, label, content_markdown, sort_order) values ('50000000-0000-4000-8000-000009000581', '40000000-0000-4000-8000-000000900058', 'A', '$\begin{pmatrix}2&-1\\3&4\end{pmatrix}$', 1), ('50000000-0000-4000-8000-000009000582', '40000000-0000-4000-8000-000000900058', 'B', '$\begin{pmatrix}3&2\\4&-1\end{pmatrix}$', 2), ('50000000-0000-4000-8000-000009000583', '40000000-0000-4000-8000-000000900058', 'C', '$\begin{pmatrix}-1&4\\2&3\end{pmatrix}$', 3), ('50000000-0000-4000-8000-000009000584', '40000000-0000-4000-8000-000000900058', 'D', '$\begin{pmatrix}2&3\\-1&4\end{pmatrix}$', 4)
insert into public.question_answer_keys (question_id, correct_option_id) values ('40000000-0000-4000-8000-000000900058', '50000000-0000-4000-8000-000009000584') on conflict (question_id) do update set correct_option_id=excluded.correct_option_id;
insert into public.question_taxonomy_tags (question_id, taxonomy_node_id, is_primary) values ('40000000-0000-4000-8000-000000900058', '30000000-0000-4000-8000-000000090015', true) on conflict (question_id, taxonomy_node_id) do update set is_primary=excluded.is_primary;
insert into public.question_hints (id, question_id, content_markdown, sort_order) values ('60000000-0000-4000-8000-000009000581', '40000000-0000-4000-8000-000000900058', 'As colunas da matriz são imagens dos vetores da base do domínio.', 1), ('60000000-0000-4000-8000-000009000582', '40000000-0000-4000-8000-000000900058', 'A primeira imagem ocupa a primeira coluna.', 2), ('60000000-0000-4000-8000-000009000583', '40000000-0000-4000-8000-000000900058', 'Preserve a ordem $(e_1,e_2)$.', 3)
insert into public.question_solutions (question_id, final_answer_markdown, explanation_markdown) values ('40000000-0000-4000-8000-000000900058', '$\begin{pmatrix}2&3\\-1&4\end{pmatrix}$', 'Uma matriz de transformação é construída coluna a coluna: a coluna $j$ contém as coordenadas da imagem do $j$-ésimo vetor da base do domínio.') on conflict (question_id) do update set final_answer_markdown=excluded.final_answer_markdown, explanation_markdown=excluded.explanation_markdown;
insert into public.question_solution_steps (id, question_id, title, content_markdown, sort_order) values ('70000000-0000-4000-8000-000009000581', '40000000-0000-4000-8000-000000900058', 'Associe a primeira coluna', '$T(e_1)=(2,-1)$.', 1), ('70000000-0000-4000-8000-000009000582', '40000000-0000-4000-8000-000000900058', 'Associe a segunda', '$T(e_2)=(3,4)$.', 2), ('70000000-0000-4000-8000-000009000583', '40000000-0000-4000-8000-000000900058', 'Monte a matriz', '$[T]=\begin{pmatrix}2&3\\-1&4\end{pmatrix}$.', 3), ('70000000-0000-4000-8000-000009000584', '40000000-0000-4000-8000-000000900058', 'Confira', 'Multiplicar por $e_1$ ou $e_2$ recupera a coluna correspondente.', 4)
insert into public.questions (id, subject_id, source_id, kind, difficulty, publication_status, statement_markdown) values ('40000000-0000-4000-8000-000000900059', '20000000-0000-4000-8000-000000000002', '10000000-0000-4000-8000-000000090004', 'multiple_choice', 'easy', 'published', 'Qual matriz representa a reflexão de $\mathbb R^2$ em torno do eixo $x$?')
insert into public.question_options (id, question_id, label, content_markdown, sort_order) values ('50000000-0000-4000-8000-000009000591', '40000000-0000-4000-8000-000000900059', 'A', '$\begin{pmatrix}1&0\\0&-1\end{pmatrix}$', 1), ('50000000-0000-4000-8000-000009000592', '40000000-0000-4000-8000-000000900059', 'B', '$\begin{pmatrix}-1&0\\0&1\end{pmatrix}$', 2), ('50000000-0000-4000-8000-000009000593', '40000000-0000-4000-8000-000000900059', 'C', '$\begin{pmatrix}0&1\\1&0\end{pmatrix}$', 3), ('50000000-0000-4000-8000-000009000594', '40000000-0000-4000-8000-000000900059', 'D', '$\begin{pmatrix}-1&0\\0&-1\end{pmatrix}$', 4)
insert into public.question_answer_keys (question_id, correct_option_id) values ('40000000-0000-4000-8000-000000900059', '50000000-0000-4000-8000-000009000591') on conflict (question_id) do update set correct_option_id=excluded.correct_option_id;
insert into public.question_taxonomy_tags (question_id, taxonomy_node_id, is_primary) values ('40000000-0000-4000-8000-000000900059', '30000000-0000-4000-8000-000000090017', true) on conflict (question_id, taxonomy_node_id) do update set is_primary=excluded.is_primary;
insert into public.question_hints (id, question_id, content_markdown, sort_order) values ('60000000-0000-4000-8000-000009000591', '40000000-0000-4000-8000-000000900059', 'Pontos do eixo $x$ devem permanecer fixos.', 1), ('60000000-0000-4000-8000-000009000592', '40000000-0000-4000-8000-000000900059', 'A componente vertical deve trocar de sinal.', 2), ('60000000-0000-4000-8000-000009000593', '40000000-0000-4000-8000-000000900059', 'A transformação leva $(x,y)$ em $(x,-y)$.', 3)
insert into public.question_solutions (question_id, final_answer_markdown, explanation_markdown) values ('40000000-0000-4000-8000-000000900059', '$\begin{pmatrix}1&0\\0&-1\end{pmatrix}$', 'Refletir no eixo $x$ preserva a coordenada horizontal e inverte a vertical. Uma matriz diagonal com fatores $1$ e $-1$ produz exatamente esse efeito.') on conflict (question_id) do update set final_answer_markdown=excluded.final_answer_markdown, explanation_markdown=excluded.explanation_markdown;
insert into public.question_solution_steps (id, question_id, title, content_markdown, sort_order) values ('70000000-0000-4000-8000-000009000591', '40000000-0000-4000-8000-000000900059', 'Determine a imagem geral', 'A reflexão envia $(x,y)$ em $(x,-y)$.', 1), ('70000000-0000-4000-8000-000009000592', '40000000-0000-4000-8000-000000900059', 'Imagem de $e_1$', 'O vetor $(1,0)$ permanece $(1,0)$.', 2), ('70000000-0000-4000-8000-000009000593', '40000000-0000-4000-8000-000000900059', 'Imagem de $e_2$', 'O vetor $(0,1)$ vira $(0,-1)$.', 3), ('70000000-0000-4000-8000-000009000594', '40000000-0000-4000-8000-000000900059', 'Monte pelas colunas', 'As imagens formam a matriz diagonal indicada.', 4)
insert into public.questions (id, subject_id, source_id, kind, difficulty, publication_status, statement_markdown) values ('40000000-0000-4000-8000-000000900060', '20000000-0000-4000-8000-000000000002', '10000000-0000-4000-8000-000000090004', 'multiple_choice', 'easy', 'published', 'Considere as transformações $S(x,y)=(x+y,y)$ e $T(x,y)=(2x,-y)$. Calcule $(T\circ S)(1,2)$.')
insert into public.question_options (id, question_id, label, content_markdown, sort_order) values ('50000000-0000-4000-8000-000009000601', '40000000-0000-4000-8000-000000900060', 'A', '$(6,2)$', 1), ('50000000-0000-4000-8000-000009000602', '40000000-0000-4000-8000-000000900060', 'B', '$(6,-2)$', 2), ('50000000-0000-4000-8000-000009000603', '40000000-0000-4000-8000-000000900060', 'C', '$(0,-2)$', 3), ('50000000-0000-4000-8000-000009000604', '40000000-0000-4000-8000-000000900060', 'D', '$(2,-2)$', 4)
insert into public.question_answer_keys (question_id, correct_option_id) values ('40000000-0000-4000-8000-000000900060', '50000000-0000-4000-8000-000009000602') on conflict (question_id) do update set correct_option_id=excluded.correct_option_id;
insert into public.question_taxonomy_tags (question_id, taxonomy_node_id, is_primary) values ('40000000-0000-4000-8000-000000900060', '30000000-0000-4000-8000-000000090016', true) on conflict (question_id, taxonomy_node_id) do update set is_primary=excluded.is_primary;
insert into public.question_hints (id, question_id, content_markdown, sort_order) values ('60000000-0000-4000-8000-000009000601', '40000000-0000-4000-8000-000000900060', 'Em $Tcirc S$, aplique $S$ primeiro.', 1), ('60000000-0000-4000-8000-000009000602', '40000000-0000-4000-8000-000000900060', 'Calcule $S(1,2)$ antes de usar $T$.', 2), ('60000000-0000-4000-8000-000009000603', '40000000-0000-4000-8000-000000900060', 'Confira o sinal introduzido na segunda componente por $T$.', 3)
insert into public.question_solutions (question_id, final_answer_markdown, explanation_markdown) values ('40000000-0000-4000-8000-000000900060', '$(6,-2)$', 'A composição é lida da direita para a esquerda. A saída de $S$ torna-se a entrada de $T$; inverter essa ordem produz uma transformação diferente.') on conflict (question_id) do update set final_answer_markdown=excluded.final_answer_markdown, explanation_markdown=excluded.explanation_markdown;
insert into public.question_solution_steps (id, question_id, title, content_markdown, sort_order) values ('70000000-0000-4000-8000-000009000601', '40000000-0000-4000-8000-000000900060', 'Aplique a função interna', '$S(1,2)=(3,2)$.', 1), ('70000000-0000-4000-8000-000009000602', '40000000-0000-4000-8000-000000900060', 'Use a saída em $T$', '$T(3,2)=(2\cdot3,-2)$.', 2), ('70000000-0000-4000-8000-000009000603', '40000000-0000-4000-8000-000000900060', 'Simplifique', 'O resultado é $(6,-2)$.', 3), ('70000000-0000-4000-8000-000009000604', '40000000-0000-4000-8000-000000900060', 'Confira a ordem', '$S(T(1,2))=S(2,-2)=(0,-2)$ seria outra alternativa, mas outra composição.', 4)
insert into public.questions (id, subject_id, source_id, kind, difficulty, publication_status, statement_markdown) values ('40000000-0000-4000-8000-000000900061', '20000000-0000-4000-8000-000000000002', '10000000-0000-4000-8000-000000090004', 'multiple_choice', 'medium', 'published', 'Uma transformação linear $T:\mathbb R^4\to\mathbb R^5$ tem posto $4$. Qual conclusão é obrigatória?')
insert into public.question_options (id, question_id, label, content_markdown, sort_order) values ('50000000-0000-4000-8000-000009000611', '40000000-0000-4000-8000-000000900061', 'A', '$ker T$ tem dimensão $1$.', 1), ('50000000-0000-4000-8000-000009000612', '40000000-0000-4000-8000-000000900061', 'B', '$T$ não pode existir.', 2), ('50000000-0000-4000-8000-000009000613', '40000000-0000-4000-8000-000000900061', 'C', '$T$ é injetiva.', 3), ('50000000-0000-4000-8000-000009000614', '40000000-0000-4000-8000-000000900061', 'D', '$T$ é sobrejetiva.', 4)
insert into public.question_answer_keys (question_id, correct_option_id) values ('40000000-0000-4000-8000-000000900061', '50000000-0000-4000-8000-000009000613') on conflict (question_id) do update set correct_option_id=excluded.correct_option_id;
insert into public.question_taxonomy_tags (question_id, taxonomy_node_id, is_primary) values ('40000000-0000-4000-8000-000000900061', '30000000-0000-4000-8000-000000090014', true) on conflict (question_id, taxonomy_node_id) do update set is_primary=excluded.is_primary;
insert into public.question_hints (id, question_id, content_markdown, sort_order) values ('60000000-0000-4000-8000-000009000611', '40000000-0000-4000-8000-000000900061', 'Compare o posto com a dimensão do domínio.', 1), ('60000000-0000-4000-8000-000009000612', '40000000-0000-4000-8000-000000900061', 'Use posto-nulidade.', 2), ('60000000-0000-4000-8000-000009000613', '40000000-0000-4000-8000-000000900061', 'Injetividade equivale a núcleo trivial.', 3)
insert into public.question_solutions (question_id, final_answer_markdown, explanation_markdown) values ('40000000-0000-4000-8000-000000900061', '$T$ é injetiva.', 'O posto já ocupa todas as quatro dimensões do domínio. Pelo teorema posto-nulidade, não sobra dimensão para o núcleo, o que caracteriza a injetividade.') on conflict (question_id) do update set final_answer_markdown=excluded.final_answer_markdown, explanation_markdown=excluded.explanation_markdown;
insert into public.question_solution_steps (id, question_id, title, content_markdown, sort_order) values ('70000000-0000-4000-8000-000009000611', '40000000-0000-4000-8000-000000900061', 'Aplique posto-nulidade', '$dimker T+\operatorname{posto}T=4$.', 1), ('70000000-0000-4000-8000-000009000612', '40000000-0000-4000-8000-000000900061', 'Substitua o posto', '$dimker T+4=4$.', 2), ('70000000-0000-4000-8000-000009000613', '40000000-0000-4000-8000-000000900061', 'Calcule a nulidade', '$dimker T=0$.', 3), ('70000000-0000-4000-8000-000009000614', '40000000-0000-4000-8000-000000900061', 'Interprete', 'O núcleo é trivial, portanto $T$ é injetiva; não pode ser sobrejetiva em $\mathbb R^5$.', 4)
insert into public.questions (id, subject_id, source_id, kind, difficulty, publication_status, statement_markdown) values ('40000000-0000-4000-8000-000000900062', '20000000-0000-4000-8000-000000000002', '10000000-0000-4000-8000-000000090004', 'multiple_choice', 'medium', 'published', 'Para qual valor de $c$ a função $F(x,y)=(3x,y+c)$ pode ser linear?')
insert into public.question_options (id, question_id, label, content_markdown, sort_order) values ('50000000-0000-4000-8000-000009000621', '40000000-0000-4000-8000-000000900062', 'A', '$c=1$', 1), ('50000000-0000-4000-8000-000009000622', '40000000-0000-4000-8000-000000900062', 'B', '$c=-1$', 2), ('50000000-0000-4000-8000-000009000623', '40000000-0000-4000-8000-000000900062', 'C', 'Qualquer $c$', 3), ('50000000-0000-4000-8000-000009000624', '40000000-0000-4000-8000-000000900062', 'D', '$c=0$', 4)
insert into public.question_answer_keys (question_id, correct_option_id) values ('40000000-0000-4000-8000-000000900062', '50000000-0000-4000-8000-000009000624') on conflict (question_id) do update set correct_option_id=excluded.correct_option_id;
insert into public.question_taxonomy_tags (question_id, taxonomy_node_id, is_primary) values ('40000000-0000-4000-8000-000000900062', '30000000-0000-4000-8000-000000090014', true) on conflict (question_id, taxonomy_node_id) do update set is_primary=excluded.is_primary;
insert into public.question_hints (id, question_id, content_markdown, sort_order) values ('60000000-0000-4000-8000-000009000621', '40000000-0000-4000-8000-000000900062', 'Teste a imagem do vetor nulo.', 1), ('60000000-0000-4000-8000-000009000622', '40000000-0000-4000-8000-000000900062', 'Uma transformação linear não pode ter deslocamento constante.', 2), ('60000000-0000-4000-8000-000009000623', '40000000-0000-4000-8000-000000900062', 'A primeira componente já é homogênea; concentre-se na segunda.', 3)
insert into public.question_solutions (question_id, final_answer_markdown, explanation_markdown) values ('40000000-0000-4000-8000-000000900062', '$c=0$', 'O termo constante desloca todas as saídas e faz o vetor nulo sair da origem. Somente quando ele desaparece a fórmula passa a ser dada por multiplicações lineares das entradas.') on conflict (question_id) do update set final_answer_markdown=excluded.final_answer_markdown, explanation_markdown=excluded.explanation_markdown;
insert into public.question_solution_steps (id, question_id, title, content_markdown, sort_order) values ('70000000-0000-4000-8000-000009000621', '40000000-0000-4000-8000-000000900062', 'Calcule a imagem do zero', '$F(0,0)=(0,c)$.', 1), ('70000000-0000-4000-8000-000009000622', '40000000-0000-4000-8000-000000900062', 'Imponha a condição linear', 'Precisamos de $F(0,0)=(0,0)$.', 2), ('70000000-0000-4000-8000-000009000623', '40000000-0000-4000-8000-000000900062', 'Resolva o parâmetro', 'Isso exige $c=0$.', 3), ('70000000-0000-4000-8000-000009000624', '40000000-0000-4000-8000-000000900062', 'Confirme a fórmula restante', 'Com $c=0$, $F(x,y)=(3x,y)$ é uma transformação matricial linear.', 4)
insert into public.questions (id, subject_id, source_id, kind, difficulty, publication_status, statement_markdown) values ('40000000-0000-4000-8000-000000900063', '20000000-0000-4000-8000-000000000002', '10000000-0000-4000-8000-000000090004', 'multiple_choice', 'medium', 'published', 'Seja $T(x,y)=(x+y,x-y)$. No domínio use a base padrão e no contradomínio a base $C=\{(1,1),(1,-1)\}$. Qual é a matriz de $T$ nessas bases?')
insert into public.question_options (id, question_id, label, content_markdown, sort_order) values ('50000000-0000-4000-8000-000009000631', '40000000-0000-4000-8000-000000900063', 'A', '$\begin{pmatrix}1&0\\0&1\end{pmatrix}$', 1), ('50000000-0000-4000-8000-000009000632', '40000000-0000-4000-8000-000000900063', 'B', '$\begin{pmatrix}1&1\\1&-1\end{pmatrix}$', 2), ('50000000-0000-4000-8000-000009000633', '40000000-0000-4000-8000-000000900063', 'C', '$\begin{pmatrix}1&0\\1&0\end{pmatrix}$', 3), ('50000000-0000-4000-8000-000009000634', '40000000-0000-4000-8000-000000900063', 'D', '$\begin{pmatrix}0&1\\1&0\end{pmatrix}$', 4)
insert into public.question_answer_keys (question_id, correct_option_id) values ('40000000-0000-4000-8000-000000900063', '50000000-0000-4000-8000-000009000631') on conflict (question_id) do update set correct_option_id=excluded.correct_option_id;
insert into public.question_taxonomy_tags (question_id, taxonomy_node_id, is_primary) values ('40000000-0000-4000-8000-000000900063', '30000000-0000-4000-8000-000000090015', true) on conflict (question_id, taxonomy_node_id) do update set is_primary=excluded.is_primary;
insert into public.question_hints (id, question_id, content_markdown, sort_order) values ('60000000-0000-4000-8000-000009000631', '40000000-0000-4000-8000-000000900063', 'Calcule $T(e_1)$ e $T(e_2)$.', 1), ('60000000-0000-4000-8000-000009000632', '40000000-0000-4000-8000-000000900063', 'Expresse cada imagem na base $C$, não na padrão.', 2), ('60000000-0000-4000-8000-000009000633', '40000000-0000-4000-8000-000000900063', 'As coordenadas obtidas formam as colunas.', 3)
insert into public.question_solutions (question_id, final_answer_markdown, explanation_markdown) values ('40000000-0000-4000-8000-000000900063', '$\begin{pmatrix}1&0\\0&1\end{pmatrix}$', 'As imagens dos vetores padrão coincidem exatamente com os vetores da base ordenada $C$. Assim suas coordenadas em $C$ são os vetores padrão, produzindo a identidade.') on conflict (question_id) do update set final_answer_markdown=excluded.final_answer_markdown, explanation_markdown=excluded.explanation_markdown;
insert into public.question_solution_steps (id, question_id, title, content_markdown, sort_order) values ('70000000-0000-4000-8000-000009000631', '40000000-0000-4000-8000-000000900063', 'Imagem de $e_1$', '$T(1,0)=(1,1)=c_1$, então $[T(e_1)]_C=(1,0)$.', 1), ('70000000-0000-4000-8000-000009000632', '40000000-0000-4000-8000-000000900063', 'Imagem de $e_2$', '$T(0,1)=(1,-1)=c_2$, então $[T(e_2)]_C=(0,1)$.', 2), ('70000000-0000-4000-8000-000009000633', '40000000-0000-4000-8000-000000900063', 'Monte as colunas', 'As colunas são $(1,0)$ e $(0,1)$.', 3), ('70000000-0000-4000-8000-000009000634', '40000000-0000-4000-8000-000000900063', 'Conclua', 'A matriz relativa é a identidade $2\times2$.', 4)
insert into public.questions (id, subject_id, source_id, kind, difficulty, publication_status, statement_markdown) values ('40000000-0000-4000-8000-000000900064', '20000000-0000-4000-8000-000000000002', '10000000-0000-4000-8000-000000090004', 'multiple_choice', 'medium', 'published', 'A transformação $T(x,y)=(x+y,x-y)$ é invertível. Qual é $T^{-1}(u,v)$?')
insert into public.question_options (id, question_id, label, content_markdown, sort_order) values ('50000000-0000-4000-8000-000009000641', '40000000-0000-4000-8000-000000900064', 'A', '$(u-v,u+v)$', 1), ('50000000-0000-4000-8000-000009000642', '40000000-0000-4000-8000-000000900064', 'B', '$((u+v)/2,(u-v)/2)$', 2), ('50000000-0000-4000-8000-000009000643', '40000000-0000-4000-8000-000000900064', 'C', '$(u+v,u-v)$', 3), ('50000000-0000-4000-8000-000009000644', '40000000-0000-4000-8000-000000900064', 'D', '$((u-v)/2,(u+v)/2)$', 4)
insert into public.question_answer_keys (question_id, correct_option_id) values ('40000000-0000-4000-8000-000000900064', '50000000-0000-4000-8000-000009000642') on conflict (question_id) do update set correct_option_id=excluded.correct_option_id;
insert into public.question_taxonomy_tags (question_id, taxonomy_node_id, is_primary) values ('40000000-0000-4000-8000-000000900064', '30000000-0000-4000-8000-000000090016', true) on conflict (question_id, taxonomy_node_id) do update set is_primary=excluded.is_primary;
insert into public.question_hints (id, question_id, content_markdown, sort_order) values ('60000000-0000-4000-8000-000009000641', '40000000-0000-4000-8000-000000900064', 'Trate $u=x+y$ e $v=x-y$ como um sistema.', 1), ('60000000-0000-4000-8000-000009000642', '40000000-0000-4000-8000-000000900064', 'Some as duas equações para isolar $x$.', 2), ('60000000-0000-4000-8000-000009000643', '40000000-0000-4000-8000-000000900064', 'Subtraia a segunda da primeira para isolar $y$.', 3)
insert into public.question_solutions (question_id, final_answer_markdown, explanation_markdown) values ('40000000-0000-4000-8000-000000900064', '$((u+v)/2,(u-v)/2)$', 'A inversa recupera as entradas a partir das duas combinações de saída. Somar e subtrair as equações separa as variáveis, e o fator dois precisa ser dividido.') on conflict (question_id) do update set final_answer_markdown=excluded.final_answer_markdown, explanation_markdown=excluded.explanation_markdown;
insert into public.question_solution_steps (id, question_id, title, content_markdown, sort_order) values ('70000000-0000-4000-8000-000009000641', '40000000-0000-4000-8000-000000900064', 'Escreva o sistema', '$u=x+y$ e $v=x-y$.', 1), ('70000000-0000-4000-8000-000009000642', '40000000-0000-4000-8000-000000900064', 'Isole $x$', '$u+v=2x$, então $x=(u+v)/2$.', 2), ('70000000-0000-4000-8000-000009000643', '40000000-0000-4000-8000-000000900064', 'Isole $y$', '$u-v=2y$, então $y=(u-v)/2$.', 3), ('70000000-0000-4000-8000-000009000644', '40000000-0000-4000-8000-000000900064', 'Confira', 'Substituir essas expressões em $T$ recupera exatamente $(u,v)$.', 4)
insert into public.questions (id, subject_id, source_id, kind, difficulty, publication_status, statement_markdown) values ('40000000-0000-4000-8000-000000900065', '20000000-0000-4000-8000-000000000002', '10000000-0000-4000-8000-000000090004', 'multiple_choice', 'medium', 'published', 'Para transformações lineares compatíveis $S$ e $T$, qual inclusão é sempre verdadeira?')
insert into public.question_options (id, question_id, label, content_markdown, sort_order) values ('50000000-0000-4000-8000-000009000651', '40000000-0000-4000-8000-000000900065', 'A', '$\operatorname{Im}Ssubseteqker T$', 1), ('50000000-0000-4000-8000-000009000652', '40000000-0000-4000-8000-000000900065', 'B', '$ker(Scirc T)subseteqker T$', 2), ('50000000-0000-4000-8000-000009000653', '40000000-0000-4000-8000-000000900065', 'C', '$ker Tsubseteqker(Scirc T)$', 3), ('50000000-0000-4000-8000-000009000654', '40000000-0000-4000-8000-000000900065', 'D', '$ker Ssubseteqker T$', 4)
insert into public.question_answer_keys (question_id, correct_option_id) values ('40000000-0000-4000-8000-000000900065', '50000000-0000-4000-8000-000009000653') on conflict (question_id) do update set correct_option_id=excluded.correct_option_id;
insert into public.question_taxonomy_tags (question_id, taxonomy_node_id, is_primary) values ('40000000-0000-4000-8000-000000900065', '30000000-0000-4000-8000-000000090014', true) on conflict (question_id, taxonomy_node_id) do update set is_primary=excluded.is_primary;
insert into public.question_hints (id, question_id, content_markdown, sort_order) values ('60000000-0000-4000-8000-000009000651', '40000000-0000-4000-8000-000000900065', 'Comece com um vetor que $T$ envia a zero.', 1), ('60000000-0000-4000-8000-000009000652', '40000000-0000-4000-8000-000000900065', 'Depois aplique $S$ ao resultado.', 2), ('60000000-0000-4000-8000-000009000653', '40000000-0000-4000-8000-000000900065', 'Toda transformação linear envia zero a zero.', 3)
insert into public.question_solutions (question_id, final_answer_markdown, explanation_markdown) values ('40000000-0000-4000-8000-000000900065', '$ker Tsubseteqker(Scirc T)$', 'Se $T$ já anula um vetor, qualquer transformação linear aplicada depois continuará produzindo zero. A inclusão inversa exigiria que $S$ não anulasse novas direções.') on conflict (question_id) do update set final_answer_markdown=excluded.final_answer_markdown, explanation_markdown=excluded.explanation_markdown;
insert into public.question_solution_steps (id, question_id, title, content_markdown, sort_order) values ('70000000-0000-4000-8000-000009000651', '40000000-0000-4000-8000-000000900065', 'Escolha um vetor do núcleo', 'Seja $vinker T$, então $T(v)=0$.', 1), ('70000000-0000-4000-8000-000009000652', '40000000-0000-4000-8000-000000900065', 'Aplique a composição', '$(Scirc T)(v)=S(T(v))=S(0)$.', 2), ('70000000-0000-4000-8000-000009000653', '40000000-0000-4000-8000-000000900065', 'Use linearidade', '$S(0)=0$.', 3), ('70000000-0000-4000-8000-000009000654', '40000000-0000-4000-8000-000000900065', 'Conclua', 'Logo $vinker(Scirc T)$ e a inclusão sempre vale.', 4)
insert into public.questions (id, subject_id, source_id, kind, difficulty, publication_status, statement_markdown) values ('40000000-0000-4000-8000-000000900066', '20000000-0000-4000-8000-000000000002', '10000000-0000-4000-8000-000000090004', 'multiple_choice', 'medium', 'published', 'Uma transformação do plano é composta por uma rotação e depois uma reflexão. Qual deve ser o sinal do determinante de sua matriz?')
insert into public.question_options (id, question_id, label, content_markdown, sort_order) values ('50000000-0000-4000-8000-000009000661', '40000000-0000-4000-8000-000000900066', 'A', 'Positivo', 1), ('50000000-0000-4000-8000-000009000662', '40000000-0000-4000-8000-000000900066', 'B', 'Zero', 2), ('50000000-0000-4000-8000-000009000663', '40000000-0000-4000-8000-000000900066', 'C', 'Depende do ângulo da rotação', 3), ('50000000-0000-4000-8000-000009000664', '40000000-0000-4000-8000-000000900066', 'D', 'Negativo', 4)
insert into public.question_answer_keys (question_id, correct_option_id) values ('40000000-0000-4000-8000-000000900066', '50000000-0000-4000-8000-000009000664') on conflict (question_id) do update set correct_option_id=excluded.correct_option_id;
insert into public.question_taxonomy_tags (question_id, taxonomy_node_id, is_primary) values ('40000000-0000-4000-8000-000000900066', '30000000-0000-4000-8000-000000090017', true) on conflict (question_id, taxonomy_node_id) do update set is_primary=excluded.is_primary;
insert into public.question_hints (id, question_id, content_markdown, sort_order) values ('60000000-0000-4000-8000-000009000661', '40000000-0000-4000-8000-000000900066', 'Rotações preservam orientação.', 1), ('60000000-0000-4000-8000-000009000662', '40000000-0000-4000-8000-000000900066', 'Reflexões invertem orientação.', 2), ('60000000-0000-4000-8000-000009000663', '40000000-0000-4000-8000-000000900066', 'O determinante da composição é o produto dos determinantes.', 3)
insert into public.question_solutions (question_id, final_answer_markdown, explanation_markdown) values ('40000000-0000-4000-8000-000000900066', 'Negativo', 'Toda rotação plana tem determinante $1$, enquanto uma reflexão tem determinante $-1$. O produto é negativo independentemente do ângulo escolhido para a rotação.') on conflict (question_id) do update set final_answer_markdown=excluded.final_answer_markdown, explanation_markdown=excluded.explanation_markdown;
insert into public.question_solution_steps (id, question_id, title, content_markdown, sort_order) values ('70000000-0000-4000-8000-000009000661', '40000000-0000-4000-8000-000000900066', 'Analise a rotação', 'Sua matriz tem determinante $1$.', 1), ('70000000-0000-4000-8000-000009000662', '40000000-0000-4000-8000-000000900066', 'Analise a reflexão', 'Sua matriz tem determinante $-1$.', 2), ('70000000-0000-4000-8000-000009000663', '40000000-0000-4000-8000-000000900066', 'Use multiplicatividade', '$\det(Rotcdot Ref)=1\cdot(-1)=-1$.', 3), ('70000000-0000-4000-8000-000009000664', '40000000-0000-4000-8000-000000900066', 'Interprete', 'A composição final reverte orientação, portanto o sinal é negativo.', 4)
insert into public.questions (id, subject_id, source_id, kind, difficulty, publication_status, statement_markdown) values ('40000000-0000-4000-8000-000000900067', '20000000-0000-4000-8000-000000000002', '10000000-0000-4000-8000-000000090004', 'multiple_choice', 'hard', 'published', 'Uma transformação linear $T:\mathbb R^2\to\mathbb R^2$ satisfaz $T(1,1)=(2,0)$ e $T(1,-1)=(0,4)$. Qual é $T(3,1)$?')
insert into public.question_options (id, question_id, label, content_markdown, sort_order) values ('50000000-0000-4000-8000-000009000671', '40000000-0000-4000-8000-000000900067', 'A', '$(4,4)$', 1), ('50000000-0000-4000-8000-000009000672', '40000000-0000-4000-8000-000000900067', 'B', '$(6,4)$', 2), ('50000000-0000-4000-8000-000009000673', '40000000-0000-4000-8000-000000900067', 'C', '$(2,8)$', 3), ('50000000-0000-4000-8000-000009000674', '40000000-0000-4000-8000-000000900067', 'D', '$(4,2)$', 4)
insert into public.question_answer_keys (question_id, correct_option_id) values ('40000000-0000-4000-8000-000000900067', '50000000-0000-4000-8000-000009000671') on conflict (question_id) do update set correct_option_id=excluded.correct_option_id;
insert into public.question_taxonomy_tags (question_id, taxonomy_node_id, is_primary) values ('40000000-0000-4000-8000-000000900067', '30000000-0000-4000-8000-000000090015', true) on conflict (question_id, taxonomy_node_id) do update set is_primary=excluded.is_primary;
insert into public.question_hints (id, question_id, content_markdown, sort_order) values ('60000000-0000-4000-8000-000009000671', '40000000-0000-4000-8000-000000900067', 'Expresse $(3,1)$ na base formada pelos dois vetores dados.', 1), ('60000000-0000-4000-8000-000009000672', '40000000-0000-4000-8000-000000900067', 'Resolva $a(1,1)+b(1,-1)=(3,1)$.', 2), ('60000000-0000-4000-8000-000009000673', '40000000-0000-4000-8000-000000900067', 'Use linearidade sobre a combinação encontrada.', 3)
insert into public.question_solutions (question_id, final_answer_markdown, explanation_markdown) values ('40000000-0000-4000-8000-000000900067', '$(4,4)$', 'As imagens de uma base determinam a transformação inteira. Primeiro escrevemos a entrada nessa base; depois aplicamos os mesmos coeficientes às imagens fornecidas.') on conflict (question_id) do update set final_answer_markdown=excluded.final_answer_markdown, explanation_markdown=excluded.explanation_markdown;
insert into public.question_solution_steps (id, question_id, title, content_markdown, sort_order) values ('70000000-0000-4000-8000-000009000671', '40000000-0000-4000-8000-000000900067', 'Calcule as coordenadas', '$a+b=3$ e $a-b=1$, então $a=2$ e $b=1$.', 1), ('70000000-0000-4000-8000-000009000672', '40000000-0000-4000-8000-000000900067', 'Escreva a entrada', '$(3,1)=2(1,1)+(1,-1)$.', 2), ('70000000-0000-4000-8000-000009000673', '40000000-0000-4000-8000-000000900067', 'Aplique linearidade', '$T(3,1)=2(2,0)+(0,4)$.', 3), ('70000000-0000-4000-8000-000009000674', '40000000-0000-4000-8000-000000900067', 'Some', 'O resultado é $(4,4)$.', 4)
insert into public.questions (id, subject_id, source_id, kind, difficulty, publication_status, statement_markdown) values ('40000000-0000-4000-8000-000000900068', '20000000-0000-4000-8000-000000000002', '10000000-0000-4000-8000-000000090004', 'multiple_choice', 'hard', 'published', 'Se $T:\mathbb R^3\to\mathbb R^2$ é sobrejetiva e $U$ é um complemento de $\ker T$ em $\mathbb R^3$, o que vale para a restrição $T|_U:U\to\mathbb R^2$?')
insert into public.question_options (id, question_id, label, content_markdown, sort_order) values ('50000000-0000-4000-8000-000009000681', '40000000-0000-4000-8000-000000900068', 'A', 'Sua imagem tem dimensão $1$.', 1), ('50000000-0000-4000-8000-000009000682', '40000000-0000-4000-8000-000000900068', 'B', 'É um isomorfismo.', 2), ('50000000-0000-4000-8000-000009000683', '40000000-0000-4000-8000-000000900068', 'C', 'É a transformação nula.', 3), ('50000000-0000-4000-8000-000009000684', '40000000-0000-4000-8000-000000900068', 'D', 'Não é injetiva.', 4)
insert into public.question_answer_keys (question_id, correct_option_id) values ('40000000-0000-4000-8000-000000900068', '50000000-0000-4000-8000-000009000682') on conflict (question_id) do update set correct_option_id=excluded.correct_option_id;
insert into public.question_taxonomy_tags (question_id, taxonomy_node_id, is_primary) values ('40000000-0000-4000-8000-000000900068', '30000000-0000-4000-8000-000000090014', true) on conflict (question_id, taxonomy_node_id) do update set is_primary=excluded.is_primary;
insert into public.question_hints (id, question_id, content_markdown, sort_order) values ('60000000-0000-4000-8000-000009000681', '40000000-0000-4000-8000-000000900068', 'Use posto-nulidade para descobrir a dimensão do núcleo.', 1), ('60000000-0000-4000-8000-000009000682', '40000000-0000-4000-8000-000000900068', 'Um complemento tem interseção trivial com o núcleo.', 2), ('60000000-0000-4000-8000-000009000683', '40000000-0000-4000-8000-000000900068', 'A restrição mantém a mesma imagem porque toda classe módulo núcleo tem representante em $U$.', 3)
insert into public.question_solutions (question_id, final_answer_markdown, explanation_markdown) values ('40000000-0000-4000-8000-000000900068', 'É um isomorfismo.', 'A sobrejetividade dá posto dois e núcleo unidimensional. O complemento $U$ tem dimensão dois, não contém vetores não nulos anulados e ainda representa todas as saídas, tornando a restrição bijetiva.') on conflict (question_id) do update set final_answer_markdown=excluded.final_answer_markdown, explanation_markdown=excluded.explanation_markdown;
insert into public.question_solution_steps (id, question_id, title, content_markdown, sort_order) values ('70000000-0000-4000-8000-000009000681', '40000000-0000-4000-8000-000000900068', 'Calcule dimensões', '$dimker T=3-2=1$, então $dim U=2$.', 1), ('70000000-0000-4000-8000-000009000682', '40000000-0000-4000-8000-000000900068', 'Teste o núcleo restrito', '$Ucapker T={0}$, logo $T|_U$ é injetiva.', 2), ('70000000-0000-4000-8000-000009000683', '40000000-0000-4000-8000-000000900068', 'Use dimensões iguais', 'Uma aplicação injetiva de $U$ bidimensional em $\mathbb R^2$ é sobrejetiva.', 3), ('70000000-0000-4000-8000-000009000684', '40000000-0000-4000-8000-000000900068', 'Conclua', 'A restrição é linear e bijetiva, portanto um isomorfismo.', 4)
insert into public.questions (id, subject_id, source_id, kind, difficulty, publication_status, statement_markdown) values ('40000000-0000-4000-8000-000000900069', '20000000-0000-4000-8000-000000000002', '10000000-0000-4000-8000-000000090004', 'multiple_choice', 'hard', 'published', 'Se $T(x,y,z)=(x+y,z)$ e $S(u,v)=u+v$, qual é uma equação para $\ker(S\circ T)$?')
insert into public.question_options (id, question_id, label, content_markdown, sort_order) values ('50000000-0000-4000-8000-000009000691', '40000000-0000-4000-8000-000000900069', 'A', '$x=0$', 1), ('50000000-0000-4000-8000-000009000692', '40000000-0000-4000-8000-000000900069', 'B', '$y+z=0$', 2), ('50000000-0000-4000-8000-000009000693', '40000000-0000-4000-8000-000000900069', 'C', '$x+y+z=0$', 3), ('50000000-0000-4000-8000-000009000694', '40000000-0000-4000-8000-000000900069', 'D', '$x+y=0$ e $z=0$', 4)
insert into public.question_answer_keys (question_id, correct_option_id) values ('40000000-0000-4000-8000-000000900069', '50000000-0000-4000-8000-000009000693') on conflict (question_id) do update set correct_option_id=excluded.correct_option_id;
insert into public.question_taxonomy_tags (question_id, taxonomy_node_id, is_primary) values ('40000000-0000-4000-8000-000000900069', '30000000-0000-4000-8000-000000090016', true) on conflict (question_id, taxonomy_node_id) do update set is_primary=excluded.is_primary;
insert into public.question_hints (id, question_id, content_markdown, sort_order) values ('60000000-0000-4000-8000-000009000691', '40000000-0000-4000-8000-000000900069', 'Calcule primeiro a fórmula da composição.', 1), ('60000000-0000-4000-8000-000009000692', '40000000-0000-4000-8000-000000900069', 'A saída de $T$ tem duas componentes que entram em $S$.', 2), ('60000000-0000-4000-8000-000009000693', '40000000-0000-4000-8000-000000900069', 'Depois imponha que o escalar resultante seja zero.', 3)
insert into public.question_solutions (question_id, final_answer_markdown, explanation_markdown) values ('40000000-0000-4000-8000-000000900069', '$x+y+z=0$', 'O núcleo da composição não exige necessariamente que $T$ produza o vetor zero; basta que sua saída pertença ao núcleo de $S$. Substituir as fórmulas revela uma única equação.') on conflict (question_id) do update set final_answer_markdown=excluded.final_answer_markdown, explanation_markdown=excluded.explanation_markdown;
insert into public.question_solution_steps (id, question_id, title, content_markdown, sort_order) values ('70000000-0000-4000-8000-000009000691', '40000000-0000-4000-8000-000000900069', 'Aplique $T$', '$T(x,y,z)=(x+y,z)$.', 1), ('70000000-0000-4000-8000-000009000692', '40000000-0000-4000-8000-000000900069', 'Aplique $S$', '$S(T(x,y,z))=(x+y)+z$.', 2), ('70000000-0000-4000-8000-000009000693', '40000000-0000-4000-8000-000000900069', 'Imponha o núcleo', 'Precisamos de $x+y+z=0$.', 3), ('70000000-0000-4000-8000-000009000694', '40000000-0000-4000-8000-000000900069', 'Compare', 'Exigir $x+y=0$ e $z=0$ seria mais restritivo do que o necessário.', 4)
insert into public.questions (id, subject_id, source_id, kind, difficulty, publication_status, statement_markdown) values ('40000000-0000-4000-8000-000000900070', '20000000-0000-4000-8000-000000000002', '10000000-0000-4000-8000-000000090004', 'multiple_choice', 'hard', 'published', 'A matriz $P$ converte coordenadas da base $C$ para a base $B$. Se $A_B$ representa um operador na base $B$, qual matriz o representa na base $C$?')
insert into public.question_options (id, question_id, label, content_markdown, sort_order) values ('50000000-0000-4000-8000-000009000701', '40000000-0000-4000-8000-000000900070', 'A', '$PA_BP^{-1}$', 1), ('50000000-0000-4000-8000-000009000702', '40000000-0000-4000-8000-000000900070', 'B', '$P^{-1}A_B$', 2), ('50000000-0000-4000-8000-000009000703', '40000000-0000-4000-8000-000000900070', 'C', '$A_BP^{-1}$', 3), ('50000000-0000-4000-8000-000009000704', '40000000-0000-4000-8000-000000900070', 'D', '$P^{-1}A_BP$', 4)
insert into public.question_answer_keys (question_id, correct_option_id) values ('40000000-0000-4000-8000-000000900070', '50000000-0000-4000-8000-000009000704') on conflict (question_id) do update set correct_option_id=excluded.correct_option_id;
insert into public.question_taxonomy_tags (question_id, taxonomy_node_id, is_primary) values ('40000000-0000-4000-8000-000000900070', '30000000-0000-4000-8000-000000090016', true) on conflict (question_id, taxonomy_node_id) do update set is_primary=excluded.is_primary;
insert into public.question_hints (id, question_id, content_markdown, sort_order) values ('60000000-0000-4000-8000-000009000701', '40000000-0000-4000-8000-000000900070', 'Comece com coordenadas em $C$ e converta-as para $B$.', 1), ('60000000-0000-4000-8000-000009000702', '40000000-0000-4000-8000-000000900070', 'Aplique $A_B$ no sistema de coordenadas correto.', 2), ('60000000-0000-4000-8000-000009000703', '40000000-0000-4000-8000-000000900070', 'Converta a saída de volta usando $P^{-1}$.', 3)
insert into public.question_solutions (question_id, final_answer_markdown, explanation_markdown) values ('40000000-0000-4000-8000-000000900070', '$P^{-1}A_BP$', 'Mudar a representação de um operador exige converter a entrada, aplicar a matriz antiga e desfazer a conversão na saída. Essa conjugação é a relação de semelhança.') on conflict (question_id) do update set final_answer_markdown=excluded.final_answer_markdown, explanation_markdown=excluded.explanation_markdown;
insert into public.question_solution_steps (id, question_id, title, content_markdown, sort_order) values ('70000000-0000-4000-8000-000009000701', '40000000-0000-4000-8000-000000900070', 'Converta a entrada', '$[v]_B=P[v]_C$.', 1), ('70000000-0000-4000-8000-000009000702', '40000000-0000-4000-8000-000000900070', 'Aplique o operador', '$[T(v)]_B=A_BP[v]_C$.', 2), ('70000000-0000-4000-8000-000009000703', '40000000-0000-4000-8000-000000900070', 'Volte para $C$', '$[T(v)]_C=P^{-1}A_BP[v]_C$.', 3), ('70000000-0000-4000-8000-000009000704', '40000000-0000-4000-8000-000000900070', 'Identifique', 'Logo $A_C=P^{-1}A_BP$.', 4)
insert into public.questions (id, subject_id, source_id, kind, difficulty, publication_status, statement_markdown) values ('40000000-0000-4000-8000-000000900071', '20000000-0000-4000-8000-000000000002', '10000000-0000-4000-8000-000000090004', 'multiple_choice', 'hard', 'published', 'Uma transformação linear $P$ satisfaz $P^2=P$. Se $v=P(u)$ pertence à imagem de $P$, o que necessariamente ocorre ao aplicar $P$ novamente?')
insert into public.question_options (id, question_id, label, content_markdown, sort_order) values ('50000000-0000-4000-8000-000009000711', '40000000-0000-4000-8000-000000900071', 'A', '$P(v)=v$', 1), ('50000000-0000-4000-8000-000009000712', '40000000-0000-4000-8000-000000900071', 'B', '$P(v)=0$', 2), ('50000000-0000-4000-8000-000009000713', '40000000-0000-4000-8000-000000900071', 'C', '$P(v)=-v$', 3), ('50000000-0000-4000-8000-000009000714', '40000000-0000-4000-8000-000000900071', 'D', '$P(v)=u$', 4)
insert into public.question_answer_keys (question_id, correct_option_id) values ('40000000-0000-4000-8000-000000900071', '50000000-0000-4000-8000-000009000711') on conflict (question_id) do update set correct_option_id=excluded.correct_option_id;
insert into public.question_taxonomy_tags (question_id, taxonomy_node_id, is_primary) values ('40000000-0000-4000-8000-000000900071', '30000000-0000-4000-8000-000000090017', true) on conflict (question_id, taxonomy_node_id) do update set is_primary=excluded.is_primary;
insert into public.question_hints (id, question_id, content_markdown, sort_order) values ('60000000-0000-4000-8000-000009000711', '40000000-0000-4000-8000-000000900071', 'Substitua $v=P(u)$ na expressão $P(v)$.', 1), ('60000000-0000-4000-8000-000009000712', '40000000-0000-4000-8000-000000900071', 'Use a identidade $P^2=P$.', 2), ('60000000-0000-4000-8000-000009000713', '40000000-0000-4000-8000-000000900071', 'Interprete o resultado para vetores que já estão na imagem.', 3)
insert into public.question_solutions (question_id, final_answer_markdown, explanation_markdown) values ('40000000-0000-4000-8000-000000900071', '$P(v)=v$', 'A identidade idempotente caracteriza projeções: depois que um vetor chega ao subespaço imagem, novas aplicações não o alteram. Isso não exige que a projeção seja ortogonal.') on conflict (question_id) do update set final_answer_markdown=excluded.final_answer_markdown, explanation_markdown=excluded.explanation_markdown;
insert into public.question_solution_steps (id, question_id, title, content_markdown, sort_order) values ('70000000-0000-4000-8000-000009000711', '40000000-0000-4000-8000-000000900071', 'Use a origem de $v$', '$v=P(u)$.', 1), ('70000000-0000-4000-8000-000009000712', '40000000-0000-4000-8000-000000900071', 'Aplique $P$', '$P(v)=P(P(u))=P^2(u)$.', 2), ('70000000-0000-4000-8000-000009000713', '40000000-0000-4000-8000-000000900071', 'Use idempotência', '$P^2(u)=P(u)$.', 3), ('70000000-0000-4000-8000-000009000714', '40000000-0000-4000-8000-000000900071', 'Conclua', '$P(v)=v$, então a imagem é o conjunto de pontos fixos de $P$.', 4)
insert into public.questions (id, subject_id, source_id, kind, difficulty, publication_status, statement_markdown) values ('40000000-0000-4000-8000-000000900072', '20000000-0000-4000-8000-000000000002', '10000000-0000-4000-8000-000000090004', 'multiple_choice', 'hard', 'published', 'Um operador $T$ satisfaz $T(v_1)=2v_1$ e $T(v_2)=-v_2$, onde $(v_1,v_2)$ é uma base. Se $w=3v_1+4v_2$, qual é $T^3(w)$?')
insert into public.question_options (id, question_id, label, content_markdown, sort_order) values ('50000000-0000-4000-8000-000009000721', '40000000-0000-4000-8000-000000900072', 'A', '$8v_1-v_2$', 1), ('50000000-0000-4000-8000-000009000722', '40000000-0000-4000-8000-000000900072', 'B', '$24v_1-4v_2$', 2), ('50000000-0000-4000-8000-000009000723', '40000000-0000-4000-8000-000000900072', 'C', '$6v_1-4v_2$', 3), ('50000000-0000-4000-8000-000009000724', '40000000-0000-4000-8000-000000900072', 'D', '$24v_1+4v_2$', 4)
insert into public.question_answer_keys (question_id, correct_option_id) values ('40000000-0000-4000-8000-000000900072', '50000000-0000-4000-8000-000009000722') on conflict (question_id) do update set correct_option_id=excluded.correct_option_id;
insert into public.question_taxonomy_tags (question_id, taxonomy_node_id, is_primary) values ('40000000-0000-4000-8000-000000900072', '30000000-0000-4000-8000-000000090015', true) on conflict (question_id, taxonomy_node_id) do update set is_primary=excluded.is_primary;
insert into public.question_hints (id, question_id, content_markdown, sort_order) values ('60000000-0000-4000-8000-000009000721', '40000000-0000-4000-8000-000000900072', 'Cada vetor da base permanece em sua própria direção sob $T$.', 1), ('60000000-0000-4000-8000-000009000722', '40000000-0000-4000-8000-000000900072', 'Ao aplicar $T$ três vezes, eleve os fatores escalares à terceira potência.', 2), ('60000000-0000-4000-8000-000009000723', '40000000-0000-4000-8000-000000900072', 'Mantenha os coeficientes originais de $w$.', 3)
insert into public.question_solutions (question_id, final_answer_markdown, explanation_markdown) values ('40000000-0000-4000-8000-000000900072', '$24v_1-4v_2$', 'Na base fornecida, a matriz de $T$ é diagonal. Potências do operador elevam cada fator diagonal à potência correspondente, sem misturar as duas direções.') on conflict (question_id) do update set final_answer_markdown=excluded.final_answer_markdown, explanation_markdown=excluded.explanation_markdown;
insert into public.question_solution_steps (id, question_id, title, content_markdown, sort_order) values ('70000000-0000-4000-8000-000009000721', '40000000-0000-4000-8000-000000900072', 'Use linearidade', '$T^3(w)=3T^3(v_1)+4T^3(v_2)$.', 1), ('70000000-0000-4000-8000-000009000722', '40000000-0000-4000-8000-000000900072', 'Calcule a primeira direção', '$T^3(v_1)=2^3v_1=8v_1$.', 2), ('70000000-0000-4000-8000-000009000723', '40000000-0000-4000-8000-000000900072', 'Calcule a segunda', '$T^3(v_2)=(-1)^3v_2=-v_2$.', 3), ('70000000-0000-4000-8000-000009000724', '40000000-0000-4000-8000-000000900072', 'Combine', '$3\cdot8v_1+4(-v_2)=24v_1-4v_2$.', 4)
